#include <stdio.h>

unsigned long long f(unsigned int n)
{
    if (n == 0) {
        return 1;
    }
    return n * f(n - 1);
}

int main(void)
{
    printf("%llu\n", f(4));
    return 0;
}

#include <stdio.h>

void show(int n)
{
    if (n == 0) {
        return;
    }
    show(n - 1);
    printf("%d\n", n);
}

int main(void)
{
    show(3);
    return 0;
}

#include <stdio.h>

int f(int n)
{
    if (n < 2) {
        return n;
    }
    return f(n - 1) + f(n - 2);
}

int main(void)
{
    printf("%d\n", f(6));
    return 0;
}

examQuestions.question:
Four factorial calls combine on return. Which product is printed?

#include <stdio.h>

unsigned long long f(unsigned int n)
{
    if (n == 0) {
        return 1;
    }
    return n * f(n - 1);
}

int main(void)
{
    printf("%llu\n", f(4));
    return 0;
}
